const navigate = useNavigate();

navigate('/hotels');                          // push a new entry
navigate(-1);                                // one step back
navigate('/login', { replace: true });       // replace the current entry
navigate('/hotels/7', { state: { from: 'search' } });

const [searchParams, setSearchParams] = useSearchParams();

const city = searchParams.get('city') ?? '';

// object form replaces the whole query string
setSearchParams({ city: 'Eger' });

// merge form, the safe one when other keys matter
const next = new URLSearchParams(searchParams);
if (city) next.set('city', city); else next.delete('city');
setSearchParams(next, { replace: true });

function RequireAuth({ children }) {
    const { user } = useAuth();
    const location = useLocation();

    if (!user) {
        // replace so the back button does not loop between login and the page
        return <Navigate to="/login" replace state={{ from: location }} />;
    }
    return children;
}

body:
`Navigate` renders nothing. It changes the location as soon as it renders, which makes it right inside a guard component and wrong inside a handler, where `useNavigate` is clearer.

The matching pair is a login page that sends the user back:

```jsx
const from = useLocation().state?.from?.pathname ?? '/';
navigate(from, { replace: true });
```

